56	                                                              : (ss + samplesPerRead);
57	                }
58	            else {
59	                (val3, val2, val1, val0) = mem[n][samp];
60	                if (ss == NSTREAM_INT - 1) {
61	                    buff[n][NSTREAM_INT - 1][dd] = val0;
62	                    buff[n][0][dd + 1] = val1;
63	                    buff[n][1][dd + 1] = val2;
64	                    buff[n][2][dd + 1] = val3;
65	                } else if (ss == NSTREAM_INT - 2) {
66	                    buff[n][NSTREAM_INT - 2][dd] = val0;
67	                    buff[n][NSTREAM_INT - 1][dd] = val1;
68	                    buff[n][0][dd + 1] = val2;
69	                    buff[n][1][dd + 1] = val3;
70	                } else if (ss == NSTREAM_INT - 3) {
71	                    buff[n][NSTREAM_INT - 3][dd] = val0;
72	                    buff[n][NSTREAM_INT - 2][dd] = val1;
73	                    buff[n][NSTREAM_INT - 1][dd] = val2;
74	                    buff[n][0][dd + 1] = val3;
75	                } else {
76	                    buff[n][ss][dd] = val0;
77	                    buff[n][ss + 1][dd] = val1;
78	                    buff[n][ss + 2][dd] = val2;
79	                    buff[n][ss + 3][dd] = val3;
80	                }
81	
82	                // Advance:
83	                dd = (ss >= NSTREAM_INT - samplesPerRead) ? dd + 1 : dd;
84	                ss = (ss >= NSTREAM_INT - samplesPerRead) ? (ss + samplesPerRead - NSTREAM_INT) : (ss + samplesPerRead);
85	            }
86	        } // col
87	    }
88	}
89	
90	void mm2s_str1(TT_DATA mem[NITER][memSizeAct],
91	               TT_STREAM sig_o[NSTREAM_INT]) // memSizeAct = 256;  2*memSizeAct/NSTREAM_INT = 128
92	{
93	LOAD_NITER:
94	    for (int n = 0; n < NITER; n++) {
95	    LOAD_SAMP:
96	        for (int samp = 0, dd = 0, ss = 0; samp < (memSizeAct); samp += 1) {
97	#pragma HLS pipeline II = 1
98	            sig_o[0].write(mem[n][samp]);
99	        }
100	    }
101	}
102	
103	// ------------------------------------------------------------
104	// Transmit
105	// ------------------------------------------------------------
106	
107	void transmit(TT_SAMPLE (&buff)[NITER][NSTREAM_INT][(samplesPerRead * memSizeAct) / NSTREAM_INT],
108	              TT_STREAM sig_o[NSTREAM_INT]) {
109	REPEAT:
110	    for (int nn = 0; nn < NITER; nn++) { // 4
111	    RUN_DEPTH:
112	        for (int cc = 0, rr = 0, dd = 0; cc < (samplesPerRead * memSizeAct) / NSTREAM_INT; cc += samplesPerRead) {
113	#pragma HLS PIPELINE II = 1
114	        STREAM1:
115	            for (int ss = 0; ss < NSTREAM_INT; ss++) {
116	                TT_SAMPLE val0 = buff[nn][ss][cc];
117	                TT_SAMPLE val1 = buff[nn][ss][cc + 1];
118	                if
119	                    constexpr(samplesPerRead == 2) { sig_o[ss].write((val1, val0)); }
120	                else {
121	                    TT_SAMPLE val0 = buff[nn][ss][cc];
122	                    TT_SAMPLE val1 = buff[nn][ss][cc + 1];
123	                    TT_SAMPLE val2 = buff[nn][ss][cc + 2];
124	                    TT_SAMPLE val3 = buff[nn][ss][cc + 3];
125	                    // printf("buff[%d][%d][%d] = %d, %d\n", nn, ss, cc, buff[nn][ss][cc] >>16, buff[nn][ss][cc] %
126	                    // (1<<15));
127	                    // printf("buff[%d][%d][%d] = %d, %d\n", nn, ss, cc+1, buff[nn][ss][cc+1] >>16, buff[nn][ss][cc+1] %
128	                    // (1<<15));
129	                    // printf("buff[%d][%d][%d] = %d, %d\n", nn, ss, cc+2, buff[nn][ss][cc+2] >>16, buff[nn][ss][cc+2] %
130	                    // (1<<15));
131	                    // printf("buff[%d][%d][%d] = %d, %d\n", nn, ss, cc+3, buff[nn][ss][cc+3] >>16, buff[nn][ss][cc+3] %
132	                    // (1<<15));
133	                    sig_o[ss].write((val3, val2, val1, val0));
134	                }
135	            } // ss
136	        }     // cc
137	    }         // nn
138	}
